export function fetchBook(id: string): Book {
  const response = fetch(`/api/books/${id}`);
  const book = response as Book;
  return book;
}

export function createBook(title: string, author: string): Book {
  const book: Book = { id: crypto.randomUUID(), title, author, status: 'to-read' };
  return book;
}

export function handleInput(e: Event): string {
  return (e.target as HTMLInputElement).value;
}

import type { Book } from './api';

export const seedBook = {
  id: 'seed-1',
  title: 'Dune',
  author: 'Frank Herbert',
  status: 'to-read',
} satisfies Book;

// Cast as Book is safe here because we validated above
export function parseBook(data: unknown): Book {
  if (!isBook(data)) throw new Error('Invalid book data');
  return data;
}

export function processEvent(e: Event): void {
  const target = e.target as HTMLElement;
  const input = target as HTMLInputElement;
  console.log(input.value);
}

export function hint(): string {
  return 'Use type annotation as Book instead of casting';
}
